#!/usr/bin/env python3
"""Generate six home-page design options with identical content, then a gallery page."""
from pathlib import Path
OUT = Path(__file__).parent
HUBS = [("01", "Project finance", "PROJECTS", "Project Team", "Procurement, grants, PO & payment, year-end, petty cash, VAT, events, filing", "9 modules"),
        ("02", "Field operations", "FOMA", "Field offices", "PO & payment requests, missions, expense claims, reports, forecast", "6 workflows"),
        ("03", "Practical resources", "TOOLS", "Templates & checklists", "Documents, checklists, calculators, rules at a glance, glossary", "20+ tools"),
        ("04", "Smart guidance", "DECISION ENGINES", "Your case → route", "Answer a few questions, get the route, controls and file pack", "9 engines")]
ICONS = ["▤", "▦", "▣", "◇"]
TASKS = [("⚖", "Procure something"), ("±", "Revise a budget"), ("▤", "Prepare a PO or payment"), ("◷", "Close the financial year"),
         ("✦", "Manage a grant"), ("✈", "Mission or claim"), ("▦", "Organise the file"), ("▥", "Financial report")]
RULES = [("Direct award · goods/services", "≤ €2,000"), ("Direct award · intellectual", "≤ €6,000"), ("Legal review · XB / mixed", "≥ €55,000"),
         ("International public call", "≥ €184,000"), ("Grant competitive call", "≥ €15,000"), ("JP heading → Addendum", "> 25%")]

def page(name, css, fonts=""):
    hubs = "".join(f'<a class="hub h{i}"><span class="k">{n} / {k}</span><span class="ic">{ICONS[i]}</span><b>{t}</b><em>{s}</em><p>{d}</p><span class="meta">{m}</span><span class="go">→</span></a>' for i, (n, k, t, s, d, m) in enumerate(HUBS))
    tasks = "".join(f'<a class="task t{i%4}"><i>{ic}</i><span>{t}</span></a>' for i, (ic, t) in enumerate(TASKS))
    rules = "".join(f"<li><span>{a}</span><b>{b}</b></li>" for a, b in RULES)
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{name}</title>{fonts}<style>*{{box-sizing:border-box}}body{{margin:0}}a{{text-decoration:none;color:inherit;cursor:pointer}}h1,h2,p{{margin:0}}ul{{list-style:none;margin:0;padding:0}}{css}</style></head><body>
<div class="app"><aside class="side"><div class="brand"><span class="mark">FG</span><span><b>Financial Guide</b><small>Council of Europe · Projects</small></span></div>
<nav><a class="on">⌂ Home</a><span class="grp">Projects</span><a>⚖ Procurement</a><a>✦ Grants</a><a>↔ PO & payment</a><a>◷ End of year</a><span class="grp">FOMA</span><a>🧾 PO request</a><a>✈ Mission order</a><a>▥ Reports</a><span class="grp">Tools & engines</span><a>▣ Tools</a><a>◇ Decision engines</a></nav></aside>
<main><header class="top"><div class="search">⌕ Search procedures, rules, documents… <kbd>Ctrl K</kbd></div><span class="chip">My Case · 2</span></header>
<section class="hero"><span class="eyebrow">Financial & Procurement Guide</span><h1>Guidance. Decisions. Templates.<br><span>All in one place.</span></h1><p>Start from your role or your task — every path ends with the applicable rule, the route for your case and the documents to keep.</p></section>
<section class="hubs">{hubs}</section>
<section class="lower"><div class="tasks-box"><h2>What do you need to do?</h2><div class="tasks">{tasks}</div></div><div class="rules"><h2>Key thresholds</h2><ul>{rules}</ul></div></section>
</main></div></body></html>"""

GF = lambda q: f'<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?{q}&display=swap" rel="stylesheet">'
BASE = """.app{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{padding:20px 14px}.brand{display:flex;gap:10px;align-items:center;margin-bottom:22px}.brand small{display:block;font-size:11px;opacity:.65}.mark{width:34px;height:34px;display:grid;place-items:center;font-weight:800;font-size:13px}nav{display:grid;gap:2px}nav a{padding:8px 10px;font-size:13.5px}.grp{font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;opacity:.55;padding:14px 10px 4px}main{padding:22px 34px 40px}.top{display:flex;gap:12px;align-items:center;margin-bottom:26px}.search{flex:1;max-width:520px;padding:10px 14px;font-size:13.5px;display:flex;gap:8px}.search kbd{margin-left:auto;font-size:11px;opacity:.6}.chip{margin-left:auto;padding:8px 14px;font-size:12.5px;font-weight:600}.eyebrow{font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;font-weight:700}.hero h1{margin:8px 0 10px}.hero p{max-width:620px}.hubs{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:26px 0}.hub{position:relative;display:grid;gap:6px;align-content:start;padding:20px;min-height:240px}.hub .k{font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;font-weight:700}.hub .ic{width:46px;height:46px;display:grid;place-items:center;font-size:20px;margin:8px 0}.hub b{font-size:22px;letter-spacing:-.01em}.hub em{font-style:normal;font-size:12.5px;font-weight:700}.hub p{font-size:13px;line-height:1.45;padding-right:30px}.hub .meta{font-size:11.5px;font-weight:600;margin-top:6px}.hub .go{position:absolute;right:16px;bottom:16px;width:34px;height:34px;display:grid;place-items:center;font-weight:700}.lower{display:grid;grid-template-columns:1fr 340px;gap:16px}.lower h2{font-size:16px;margin-bottom:14px}.tasks{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.task{display:flex;gap:10px;align-items:center;padding:12px;font-size:13px;font-weight:600}.task i{font-style:normal;width:30px;height:30px;display:grid;place-items:center;flex:none}.tasks-box,.rules{padding:20px}.rules li{display:flex;justify-content:space-between;padding:8px 0;font-size:13px}.rules b{font-variant-numeric:tabular-nums}"""

